class MinStack:
    """A stack that reports its smallest value.

    Each entry stores the value together with the minimum of the stack up to
    and including that entry. Popping an entry therefore restores the minimum
    that was current before it was pushed, so push, pop, top and get_min are
    all constant time.
    """

    def __init__(self):
        self._items = []  # list of (value, minimum_at_this_depth)

    def push(self, value):
        if self._items:
            current_min = self._items[-1][1]
            new_min = value if value < current_min else current_min
        else:
            new_min = value
        self._items.append((value, new_min))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty MinStack")
        value, _ = self._items.pop()
        return value

    def top(self):
        if not self._items:
            raise IndexError("top from empty MinStack")
        return self._items[-1][0]

    def get_min(self):
        if not self._items:
            raise ValueError("get_min from empty MinStack")
        return self._items[-1][1]

    def __len__(self):
        return len(self._items)
